                {
                    item.ObjectBounds = Mutagen.Bethesda.Fallout76.ObjectBounds.CreateFromBinary(frame: frame);
                    return (int)ObjectEffect_FieldIndex.ObjectBounds;
                }
                case RecordTypeInts.FULL:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.FULL = StringBinaryTranslation.Instance.Parse(
                        reader: frame.SpawnWithLength(contentLength),
                        eager: true,
                        source: StringsSource.Normal,
                        stringBinaryType: StringBinaryType.NullTerminate,
                        parseWhole: true);
                    return (int)ObjectEffect_FieldIndex.FULL;
                }
                case RecordTypeInts.MIID:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.MIID = frame.ReadUInt32();
                    return (int)ObjectEffect_FieldIndex.MIID;
                }
                case RecordTypeInts.EFID:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.BaseEffect.SetTo(FormLinkBinaryTranslation.Instance.Parse(reader: frame));
                    return (int)ObjectEffect_FieldIndex.BaseEffect;
                }
                case RecordTypeInts.EFIT:
                {
                    item.EFIT = Mutagen.Bethesda.Fallout76.ObjectEffectEFITData.CreateFromBinary(frame: frame);
                    return (int)ObjectEffect_FieldIndex.EFIT;
                }
                case RecordTypeInts.ENIT:
