                stream: new OverlayStream(slice, package),
                package: package,
                translationParams: translationParams);
        }

        public override ParseResult FillRecordType(
            OverlayStream stream,
            int finalPos,
            int offset,
            RecordType type,
            PreviousParse lastParsed,
            Dictionary<RecordType, int>? recordParseCount,
            TypedParseParams translationParams = default)
        {
            type = translationParams.ConvertToStandard(type);
            switch (type.TypeInt)
            {
                case RecordTypeInts.EDID:
                {
                    if (!lastParsed.ParsedIndex.HasValue)
                    {
                        return base.FillRecordType(
                            stream: stream,
                            finalPos: finalPos,
                            offset: offset,
                            type: type,
                            lastParsed: lastParsed,
                            recordParseCount: recordParseCount,
                            translationParams: translationParams.WithNoConverter());
                    }
                    else if (lastParsed.ParsedIndex.Value <= (int)MajorRecord_FieldIndex.EditorID)
                    {
                        _EDIDLocation = (stream.Position - offset);
                        return new ParseResult((int)ObjectEffect_FieldIndex.EDID, type);
                    }
                    else
                    {
                        switch (recordParseCount?.GetOrAdd(type) ?? 0)
                        {
                            case 0:
                            {
                                return base.FillRecordType(
                                    stream: stream,
                                    finalPos: finalPos,
                                    offset: offset,
                                    type: type,
                                    lastParsed: lastParsed,
                                    recordParseCount: recordParseCount,
                                    translationParams: translationParams.WithNoConverter());
                            }
                            case 1:
                            {
                                _EDIDLocation = (stream.Position - offset);
                                return new ParseResult((int)ObjectEffect_FieldIndex.EDID, type);
                            }
                            default:
                                throw new NotImplementedException();
                        }
                    }
                }
                case RecordTypeInts.OPDS:
                {
                    this.ObjectPlacementDefaults = BinaryOverlayList.FactoryByArray<IObjectPlacementDefaultGetter>(
                        mem: stream.RemainingMemory,
                        package: _package,
                        translationParams: translationParams,
                        getter: (s, p, recConv) => ObjectPlacementDefaultBinaryOverlay.ObjectPlacementDefaultFactory(new OverlayStream(s, p), p, recConv),
                        locs: ParseRecordLocations(
                            stream: stream,
                            trigger: ObjectPlacementDefault_Registration.TriggerSpecs,
                            triggersAlwaysAreNewRecords: true,
                            constants: _package.MetaData.Constants.SubConstants,
                            skipHeader: false));
                    return (int)ObjectEffect_FieldIndex.ObjectPlacementDefaults;
                }
                case RecordTypeInts.OBND:
                {
                    _ObjectBoundsLocation = new RangeInt32((stream.Position - offset), finalPos - offset);
                    return (int)ObjectEffect_FieldIndex.ObjectBounds;
                }
                case RecordTypeInts.FULL:
                {
                    _FULLLocation = (stream.Position - offset);
                    return (int)ObjectEffect_FieldIndex.FULL;
                }
                case RecordTypeInts.MIID:
                {
                    _MIIDLocation = (stream.Position - offset);
                    return (int)ObjectEffect_FieldIndex.MIID;
                }
                case RecordTypeInts.EFID:
                {
                    _BaseEffectLocation = (stream.Position - offset);
                    return (int)ObjectEffect_FieldIndex.BaseEffect;
                }
                case RecordTypeInts.EFIT:
                {
                    _EFITLocation = new RangeInt32((stream.Position - offset), finalPos - offset);
                    return (int)ObjectEffect_FieldIndex.EFIT;
                }
                case RecordTypeInts.ENIT:
                {
                    _ENITLocation = (stream.Position - offset);
                    return (int)ObjectEffect_FieldIndex.ENIT;
                }
                case RecordTypeInts.CODV:
                {
                    _CODVLocation = (stream.Position - offset);
                    return (int)ObjectEffect_FieldIndex.CODV;
                }
                case RecordTypeInts.CTDA:
                case RecordTypeInts.CITC:
                {
                    this.Conditions = BinaryOverlayList.FactoryByCountPerItem<IConditionGetter>(
                        stream: stream,
                        package: _package,
                        countLength: 4,
                        trigger: Condition_Registration.TriggerSpecs,
                        countType: RecordTypes.CITC,
                        translationParams: translationParams,
                        getter: (s, p, recConv) => ConditionBinaryOverlay.ConditionFactory(new OverlayStream(s, p), p, recConv),
                        skipHeader: false);
                    return (int)ObjectEffect_FieldIndex.Conditions;
                }
                case RecordTypeInts.CVT0:
                {
                    _CVT0Location = (stream.Position - offset);
                    return (int)ObjectEffect_FieldIndex.CVT0;
                }
                case RecordTypeInts.DURG:
                {
                    _DURGLocation = (stream.Position - offset);
                    return (int)ObjectEffect_FieldIndex.DURG;
                }
                case RecordTypeInts.EIES:
                {
                    _EIESLocation = (stream.Position - offset);
                    return (int)ObjectEffect_FieldIndex.EIES;
                }
                case RecordTypeInts.MAGA:
                {
                    _MAGALocation = (stream.Position - offset);
                    return (int)ObjectEffect_FieldIndex.MAGA;
                }
                case RecordTypeInts.MAGF:
                {
                    _MAGFLocation = (stream.Position - offset);
                    return (int)ObjectEffect_FieldIndex.MAGF;
                }
                case RecordTypeInts.MAGG:
                {
                    _MAGGLocation = (stream.Position - offset);
                    return (int)ObjectEffect_FieldIndex.MAGG;
                }
                default:
                    return base.FillRecordType(
                        stream: stream,
                        finalPos: finalPos,
                        offset: offset,
                        type: type,
                        lastParsed: lastParsed,
                        recordParseCount: recordParseCount,
                        translationParams: translationParams.WithNoConverter());
            }
        }
